[ExtensionOf(formDataSourceStr(InventTransferOrders, METInventTransferTableExt))]
final class METInventTransferOrdersFormExtDS_Extension
{
        


}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
     public void write()
    {
        METInventTransferTableExt metInventTransferTableExt = this.cursor();

        if (metInventTransferTableExt.InventTransferTable)
            {
                // CB678 reservation for TO
                METLegalEntityType metLegalEntityType = CompanyInfo::find().METLegalEntityType;

                switch (metLegalEntityType)
                {
                    case METLegalEntityType::Food:

                    if (InventLocation::find(InventTransferTable::findRecId(METInventTransferTableExt.InventTransferTable).inventlocationidFrom).metInventLocation().ExcludePerishables == NoYes::Yes)
                        {
                            METInventTransferTableExt.WMSOrderType = METConstants::GRONOrderType;
                        }
                        else
                        {
                            METInventTransferTableExt.WMSOrderType = METConstants::PERNOrderType;
                        }
                        break;

                    case METLegalEntityType::Liquor:
                        METInventTransferTableExt.WMSOrderType = METConstants::ALMOrderType;
                        break;

                    default: break;
                }
            }
        
            next Write();

    }

    /// <summary>
    /// Validate the record
    /// </summary>
    /// <returns>Result of the validation</returns>
    public boolean validatewrite()
    {
        boolean ret = true;
        
        METInventTransferTableExt metInventTransferTableExt = this.cursor();

        if (metInventTransferTableExt.InventTransferTable)
        {
            ret = next validatewrite();
        }

        return ret;
    }

    /// <summary>
    /// CB678 reservation for TO
    /// Make fields mandatory at form level
    /// </summary>
    public void init()
    {
        next init();

        FormDataSource fds = this;
        fds.object(fieldNum(METInventTransferTableExt, InternalCustomer)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, Route)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, RouteIdentifier)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, RouteStopNum)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, RouteStopIdentifier)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, Door)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, StagingLane)).mandatory(true);
        fds.object(fieldNum(METInventTransferTableExt, OrderSplitGroup)).mandatory(true);
    }
